/*
 * Fuzz the LIN slave receive path of the SSAS BSW stack: LinIf_HeaderIndication (the LIN
 * driver's header callback, schedule-table lookup by PID) -> LinIf_RxIndication /
 * LinIf_TxConfirmation -> LinTp (ISO 17987-2 transport, shares CanTp.c) -> Dcm, with
 * MainFunction ticks between frames.
 *
 * The LinIf and LinTp configuration is generated by mayhem/build.sh with upstream's own
 * generators (tools/generator/LinIf.py, LinTp.py) from the bootloader's configuration
 * (app/bootloader/config/LinIf/LinIf.json, LinTp/LinTp.json). The LIN driver and the Dcm
 * (upper layer, "ZeroCost" route of LinTp) are mocked: the Dcm mock buffers a request and sends
 * it back as the response.
 *
 * Input: a sequence of LIN frames [pid:1][len:1][data:len (<= 8)]. Each header is delivered with
 * LinIf_HeaderIndication; if the slave is to receive the response, the data is delivered with
 * LinIf_RxIndication; if it is to transmit, the transmission is confirmed. Then one tick.
 * Every input starts from a freshly initialised stack.
 */
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include "Std_Types.h"
#include "ComStack_Types.h"
#include "Lin.h"
#include "LinIf.h"
#include "LinTp.h"

extern const LinIf_ConfigType LinIf_Config;
extern const LinTp_ConfigType LinTp_Config;
void LinTp_Init(const LinTp_ConfigType *cfgPtr);
void LinTp_MainFunction(void);
Std_ReturnType LinTp_Transmit(PduIdType txPduId, const PduInfoType *pduInfoPtr);

