/* ---------------- harness ---------------- */
static void configure(void) {
  LinIf_Init(&LinIf_Config);
  LinTp_Init(&LinTp_Config);
  ulRxLen = 0;
  ulTxLen = 0;
  ulTxPos = 0;
  ulEcho = 0;
}

static void tick(void) {
  PduInfoType pdu;
  LinIf_MainFunction();
  LinTp_MainFunction();
  if (ulEcho) {
    ulEcho = 0;
    ulTxPos = 0;
    pdu.SduDataPtr = NULL;
    pdu.MetaDataPtr = NULL;
    pdu.SduLength = ulTxLen;
    (void)LinTp_Transmit(0, &pdu);
  }
}

/* one LIN slot: header from the master, then the response (from the master or from us) */
static void slot(uint8_t pid, const uint8_t *data, uint8_t len) {
  uint8_t resp[8];
  Lin_PduType pdu;
  Std_ReturnType ret;

  memset(&pdu, 0, sizeof(pdu));
  pdu.Pid = pid;
  ret = LinIf_HeaderIndication(0, &pdu);
  if (E_OK == ret) {
    if (LIN_FRAMERESPONSE_RX == pdu.Drc) {
      memset(resp, 0, sizeof(resp));
      memcpy(resp, data, len);
      LinIf_RxIndication(0, resp);
    } else if (LIN_FRAMERESPONSE_TX == pdu.Drc) {
      if ((NULL != pdu.SduPtr) && (pdu.Dl <= sizeof(lastTxFrame))) {
        memcpy(lastTxFrame, pdu.SduPtr, pdu.Dl); /* the driver puts the response on the bus */
        txFrames++;
      }
      LinIf_TxConfirmation(0);
    } else {
      /* ignore */
    }
  }
}

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
  size_t pos = 0;
  int i;

  configure();
  while (pos + 2 <= size) {
    uint8_t pid = data[pos];
    uint8_t len = data[pos + 1] % 9;
    pos += 2;
    if (pos + len > size) {
      len = (uint8_t)(size - pos);
    }
    slot(pid, &data[pos], len);
    pos += len;
    tick();
  }
  /* let pending transfers time out */
  for (i = 0; i < 120; i++) {
    tick();
  }
  return 0;
}
